CREATE TYPE "PlatformRole" AS ENUM ('admin', 'user');
CREATE TYPE "ClubRole" AS ENUM ('club_admin', 'member');
CREATE TYPE "TeamRole" AS ENUM ('team_admin', 'coach', 'player', 'viewer');
CREATE TYPE "MatchStatus" AS ENUM ('scheduled', 'live', 'finished', 'cancelled', 'unknown');
CREATE TYPE "MatchEventType" AS ENUM ('goal', 'assist', 'green_card', 'yellow_card', 'red_card', 'substitution', 'save', 'penalty_corner', 'penalty_stroke', 'custom');
CREATE TYPE "SyncStatus" AS ENUM ('running', 'success', 'failed');
CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"platformRole" "PlatformRole" NOT NULL DEFAULT 'user',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Club" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"externalProvider" TEXT,"externalIdentifier" TEXT,"logoUrl" TEXT,"logoLocalPath" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Club_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClubMembership" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"clubId" TEXT NOT NULL,"role" "ClubRole" NOT NULL DEFAULT 'member',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ClubMembership_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Team" ("id" TEXT NOT NULL,"clubId" TEXT NOT NULL,"name" TEXT NOT NULL,"shortName" TEXT NOT NULL,"externalProvider" TEXT,"externalIdentifier" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Team_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TeamMembership" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"teamId" TEXT NOT NULL,"role" "TeamRole" NOT NULL DEFAULT 'viewer',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TeamMembership_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Season" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"startDate" TIMESTAMP(3) NOT NULL,"endDate" TIMESTAMP(3) NOT NULL,CONSTRAINT "Season_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TeamSeason" ("id" TEXT NOT NULL,"teamId" TEXT NOT NULL,"seasonId" TEXT NOT NULL,"competition" TEXT,CONSTRAINT "TeamSeason_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Match" ("id" TEXT NOT NULL,"externalProvider" TEXT,"externalId" TEXT,"seasonId" TEXT NOT NULL,"competition" TEXT,"homeTeamId" TEXT NOT NULL,"awayTeamId" TEXT NOT NULL,"date" TIMESTAMP(3) NOT NULL,"startTime" TEXT,"venue" TEXT,"status" "MatchStatus" NOT NULL DEFAULT 'unknown',"homeScore" INTEGER,"awayScore" INTEGER,"lastSyncedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Match_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Standing" ("id" TEXT NOT NULL,"seasonId" TEXT NOT NULL,"competition" TEXT NOT NULL,"teamId" TEXT NOT NULL,"position" INTEGER NOT NULL,"played" INTEGER NOT NULL DEFAULT 0,"won" INTEGER NOT NULL DEFAULT 0,"drawn" INTEGER NOT NULL DEFAULT 0,"lost" INTEGER NOT NULL DEFAULT 0,"goalsFor" INTEGER NOT NULL DEFAULT 0,"goalsAgainst" INTEGER NOT NULL DEFAULT 0,"goalDifference" INTEGER NOT NULL DEFAULT 0,"points" INTEGER NOT NULL DEFAULT 0,"lastSyncedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Standing_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Player" ("id" TEXT NOT NULL,"teamId" TEXT NOT NULL,"userId" TEXT,"firstName" TEXT NOT NULL,"lastName" TEXT NOT NULL,"displayName" TEXT NOT NULL,"shirtNumber" INTEGER,"position" TEXT,"photoPath" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Player_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlayerMatchStats" ("id" TEXT NOT NULL,"matchId" TEXT NOT NULL,"playerId" TEXT NOT NULL,"started" BOOLEAN NOT NULL DEFAULT false,"minutesPlayed" INTEGER,"goals" INTEGER NOT NULL DEFAULT 0,"assists" INTEGER NOT NULL DEFAULT 0,"saves" INTEGER NOT NULL DEFAULT 0,"mvp" BOOLEAN NOT NULL DEFAULT false,"notes" TEXT,CONSTRAINT "PlayerMatchStats_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MatchEvent" ("id" TEXT NOT NULL,"matchId" TEXT NOT NULL,"playerId" TEXT,"relatedPlayerId" TEXT,"minute" INTEGER,"type" "MatchEventType" NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MatchEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SyncRun" ("id" TEXT NOT NULL,"teamId" TEXT NOT NULL,"status" "SyncStatus" NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"newMatches" INTEGER NOT NULL DEFAULT 0,"updatedMatches" INTEGER NOT NULL DEFAULT 0,"error" TEXT,CONSTRAINT "SyncRun_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE UNIQUE INDEX "Club_slug_key" ON "Club"("slug"); CREATE UNIQUE INDEX "ClubMembership_userId_clubId_key" ON "ClubMembership"("userId", "clubId");
CREATE INDEX "Team_externalProvider_externalIdentifier_idx" ON "Team"("externalProvider", "externalIdentifier"); CREATE UNIQUE INDEX "Team_clubId_name_key" ON "Team"("clubId", "name");
CREATE UNIQUE INDEX "TeamMembership_userId_teamId_key" ON "TeamMembership"("userId", "teamId"); CREATE UNIQUE INDEX "Season_name_key" ON "Season"("name"); CREATE UNIQUE INDEX "TeamSeason_teamId_seasonId_competition_key" ON "TeamSeason"("teamId", "seasonId", "competition");
CREATE INDEX "Match_homeTeamId_date_idx" ON "Match"("homeTeamId", "date"); CREATE INDEX "Match_awayTeamId_date_idx" ON "Match"("awayTeamId", "date"); CREATE UNIQUE INDEX "Match_externalProvider_externalId_key" ON "Match"("externalProvider", "externalId"); CREATE UNIQUE INDEX "Match_seasonId_homeTeamId_awayTeamId_date_key" ON "Match"("seasonId", "homeTeamId", "awayTeamId", "date");
CREATE UNIQUE INDEX "Standing_seasonId_competition_teamId_key" ON "Standing"("seasonId", "competition", "teamId"); CREATE UNIQUE INDEX "Player_userId_key" ON "Player"("userId"); CREATE INDEX "Player_teamId_active_idx" ON "Player"("teamId", "active"); CREATE UNIQUE INDEX "PlayerMatchStats_matchId_playerId_key" ON "PlayerMatchStats"("matchId", "playerId"); CREATE INDEX "MatchEvent_matchId_type_idx" ON "MatchEvent"("matchId", "type"); CREATE INDEX "SyncRun_teamId_startedAt_idx" ON "SyncRun"("teamId", "startedAt");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ClubMembership" ADD CONSTRAINT "ClubMembership_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ClubMembership" ADD CONSTRAINT "ClubMembership_clubId_fkey" FOREIGN KEY ("clubId") REFERENCES "Club"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Team" ADD CONSTRAINT "Team_clubId_fkey" FOREIGN KEY ("clubId") REFERENCES "Club"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TeamMembership" ADD CONSTRAINT "TeamMembership_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TeamMembership" ADD CONSTRAINT "TeamMembership_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TeamSeason" ADD CONSTRAINT "TeamSeason_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TeamSeason" ADD CONSTRAINT "TeamSeason_seasonId_fkey" FOREIGN KEY ("seasonId") REFERENCES "Season"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Match" ADD CONSTRAINT "Match_seasonId_fkey" FOREIGN KEY ("seasonId") REFERENCES "Season"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Match" ADD CONSTRAINT "Match_homeTeamId_fkey" FOREIGN KEY ("homeTeamId") REFERENCES "Team"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Match" ADD CONSTRAINT "Match_awayTeamId_fkey" FOREIGN KEY ("awayTeamId") REFERENCES "Team"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Standing" ADD CONSTRAINT "Standing_seasonId_fkey" FOREIGN KEY ("seasonId") REFERENCES "Season"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Standing" ADD CONSTRAINT "Standing_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Player" ADD CONSTRAINT "Player_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Player" ADD CONSTRAINT "Player_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "PlayerMatchStats" ADD CONSTRAINT "PlayerMatchStats_matchId_fkey" FOREIGN KEY ("matchId") REFERENCES "Match"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PlayerMatchStats" ADD CONSTRAINT "PlayerMatchStats_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "Player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MatchEvent" ADD CONSTRAINT "MatchEvent_matchId_fkey" FOREIGN KEY ("matchId") REFERENCES "Match"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "MatchEvent" ADD CONSTRAINT "MatchEvent_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "Player"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "MatchEvent" ADD CONSTRAINT "MatchEvent_relatedPlayerId_fkey" FOREIGN KEY ("relatedPlayerId") REFERENCES "Player"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SyncRun" ADD CONSTRAINT "SyncRun_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"("id") ON DELETE CASCADE ON UPDATE CASCADE;
